      "app_code": {
        "type": "string",
        "description": "appCode; defaults to session"
      },
      "client_code": {
        "type": "string",
        "description": "Owning clientCode"
      },
      "title": {
        "type": "string",
        "description": "Browser title; defaults to name. Set for camelCase page names ('Contact Us' for 'contactUs')."
      },
      "message": {
        "type": "string",
        "description": "Commit message"
      }
    },
    "required": [
      "name"
    ]
  }
}
